{
  "name": "Molecular Devices 多功能酶标仪",
  "name_en": "Molecular Devices Multimode Microplate Reader",
  "manufacturer": "Molecular Devices",
  "description": "这是一种用于读取微孔板样品信号的多功能酶标仪，可进行吸光度、荧光、化学发光、荧光偏振和时间分辨荧光检测。设备通常用于生化分析、细胞实验、免疫检测、酶活性测定和高通量筛选，并支持控温与振荡等板上实验条件控制。",
  "description_en": "A multimode microplate reader used to measure signals from samples in microplates. It supports absorbance, fluorescence, luminescence, fluorescence polarization, and time-resolved fluorescence measurements. The instrument is commonly used for biochemical assays, cell-based experiments, immunoassays, enzyme activity measurements, and high-throughput screening, with support for temperature control and plate shaking.",
  "tag_hints": [
    "microplate reading",
    "multimode plate reader",
    "absorbance measurement",
    "fluorescence assay",
    "luminescence detection",
    "fluorescence polarization",
    "time-resolved fluorescence",
    "temperature-controlled incubation"
  ],
  "actions": [
    {
      "action_name": "auto-clear_error_log",
      "description": "清除仪器错误日志。",
      "description_en": "Clear the instrument error log."
    },
    {
      "action_name": "auto-close",
      "description": "关闭酶标仪的载板抽屉或托盘。",
      "description_en": "Close the plate carrier drawer or tray of the reader."
    },
    {
      "action_name": "auto-open",
      "description": "打开酶标仪的载板抽屉或托盘。",
      "description_en": "Open the plate carrier drawer or tray of the reader."
    },
    {
      "action_name": "auto-read_absorbance",
      "description": "对微孔板执行吸光度读数。",
      "description_en": "Perform an absorbance read on a microplate."
    },
    {
      "action_name": "auto-read_error_log",
      "description": "读取仪器错误日志。",
      "description_en": "Read the instrument error log."
    },
    {
      "action_name": "auto-read_fluorescence",
      "description": "对微孔板执行荧光读数。",
      "description_en": "Perform a fluorescence read on a microplate."
    },
    {
      "action_name": "auto-read_fluorescence_polarization",
      "description": "对微孔板执行荧光偏振读数。",
      "description_en": "Perform a fluorescence polarization read on a microplate."
    },
    {
      "action_name": "auto-read_luminescence",
      "description": "对微孔板执行发光读数。",
      "description_en": "Perform a luminescence read on a microplate."
    },
    {
      "action_name": "auto-read_time_resolved_fluorescence",
      "description": "对微孔板执行时间分辨荧光读数。",
      "description_en": "Perform a time-resolved fluorescence read on a microplate."
    },
    {
      "action_name": "auto-send_command",
      "description": "向酶标仪发送设备命令。",
      "description_en": "Send a device command to the plate reader."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出当前设备配置与设置信息。",
      "description_en": "Export the current device configuration and settings."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置温度。",
      "description_en": "Set temperature."
    },
    {
      "action_name": "auto-setup",
      "description": "初始化并准备酶标仪进行操作。",
      "description_en": "Initialize and prepare the plate reader for operation."
    },
    {
      "action_name": "auto-start_shake",
      "description": "启动微孔板振荡。",
      "description_en": "Start shaking the microplate."
    },
    {
      "action_name": "auto-stop",
      "description": "停止当前仪器操作。",
      "description_en": "Stop the current instrument operation."
    },
    {
      "action_name": "auto-stop_shake",
      "description": "停止微孔板振荡。",
      "description_en": "Stop shaking the microplate."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取状态。",
      "description_en": "Get status."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取温度。",
      "description_en": "Get temperature."
    },
    {
      "action_name": "auto-get_firmware_version",
      "description": "获取固件版本。",
      "description_en": "Get firmware version."
    }
  ]
}

